{"command": "cd /workspace/work && python3 << 'PYEOF'
import subprocess, json

def ft2_get(row, ch, pat=0):
    res = subprocess.run(['ft2', 'call', 'pattern_get_cell', json.dumps({"pattern": pat, "row": row, "channel": ch})], capture_output=True, text=True)
    data = json.loads(res.stdout)
    inner = json.loads(data['content'][0]['text'])
    return inner

# Check climax pattern (6)
print('Climax pattern (6), summary by channel:')
ch_summary = {ch: [] for ch in range(8)}
for row in range(0, 64):
    for ch in range(8):
        cell = ft2_get(row, ch, 6)
        if cell['note'] > 0:
            ch_summary[ch].append((row, cell['note'], cell['instrument'], cell['volume']))

names = ['Kick', 'Snare', 'HatC', 'Open', 'Bass', 'Pad', 'Lead', 'Pluck']
for ch in range(8):
    print(f'Channel {ch} ({names[ch] if ch < len(names) else "?"}): {len(ch_summary[ch])} notes')
    if len(ch_summary[ch]) > 0:
        notes_str = ', '.join(f'r{n[0]}:n{n[1]}' for n in ch_summary[ch][:8])
        print(f'  First few: {notes_str}, ...')
